css:
.d-image-fit-dimensions{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-image-fit-dimensions *,.d-image-fit-dimensions *::before,.d-image-fit-dimensions *::after{box-sizing:border-box}
.d-image-fit-dimensions [hidden]{display:none!important}
.d-image-fit-dimensions .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-image-fit-dimensions .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-image-fit-dimensions label{display:block;margin:8px 0}
.d-image-fit-dimensions input,.d-image-fit-dimensions select,.d-image-fit-dimensions textarea,.d-image-fit-dimensions button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-image-fit-dimensions input:not([type=checkbox]):not([type=radio]),.d-image-fit-dimensions select,.d-image-fit-dimensions textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-image-fit-dimensions button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-image-fit-dimensions button:disabled{opacity:.5;cursor:default}
.d-image-fit-dimensions :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-image-fit-dimensions [aria-invalid=true]{border-color:var(--warn)!important}
.d-image-fit-dimensions .d-scroll{max-width:100%;overflow:auto}
.d-image-fit-dimensions table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-image-fit-dimensions th,.d-image-fit-dimensions td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-image-fit-dimensions caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-image-fit-dimensions progress{width:100%;accent-color:var(--ink)}
.d-image-fit-dimensions pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-image-fit-dimensions h3,.d-image-fit-dimensions p{margin:8px 0}
.d-image-fit-dimensions [aria-pressed=true],.d-image-fit-dimensions [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-image-fit-dimensions .d-grow{flex:1;min-width:100px}
.d-image-fit-dimensions summary{cursor:pointer;padding:6px 0}
.d-image-fit-dimensions ul,.d-image-fit-dimensions ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{q('[data-calculate]').onclick=()=>{const inputs=qa('input'),v=inputs.map(el=>Number(el.value));if(inputs.some(el=>!el.value.trim())||v.some(n=>!Number.isFinite(n)||n<=0||n>100000)){say('尺寸须为 0–100000 范围内的正数');return;}const ratios=[v[2]/v[0],v[3]/v[1]],scale=q('[data-mode]').value==='cover'?Math.max(...ratios):Math.min(...ratios),w=v[0]*scale,h=v[1]*scale;say('显示尺寸 '+w.toFixed(2)+' × '+h.toFixed(2)+'；水平裁切 '+Math.max(0,w-v[2]).toFixed(2)+'；垂直裁切 '+Math.max(0,h-v[3]).toFixed(2)+' 像素（两侧合计）');};})(root, q, qa, say);
}
